// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;
    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0)); }
    function testFuzz_property(address r1, address r2) public {
        // keep r2 outside the zero-address so the rule is decisive; domain stays wide otherwise
        r2 = (r2 == address(0)) ? address(0x1) : r2;
        vm.startPrank(c.owner());
        c.setRewardsRecipient(r1);
        assertEq(c.rewardsRecipient(), r1, "first set must take effect");
        c.setRewardsRecipient(r2);
        vm.stopPrank();
        // general rule: rewardsRecipient always holds the most recent argument
        assertTrue(c.rewardsRecipient() == r2, "rewardsRecipient must track the last set value");
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
